    ('5990d682-73e8-51a3-9d48-620b2c3709ba'::uuid, -- drawdown-mobilize-electric-trains
     'Find out how the trains in your region run',
     'Using your rail operator''s or transport agency''s public information, find out which train lines in your region run on electricity and which run on diesel. Draw a simple map or chart, and add any plans to electrify more lines. Post it with sources.',
     'research', 'explore', 2, 100, 'review', array['research','mapping']::text[]),
    ('3ef1924b-6179-5090-8b0c-c0ae158439c5'::uuid, -- drawdown-mobilize-electric-trucks
     'Map truck routes that pass schools and parks',
     'Find your city''s or region''s official truck route map, or note from a safe spot where delivery and freight trucks travel near you. Mark where those routes pass schools, parks or homes, and add any public plans for cleaner delivery trucks. Post your map with sources.',
     'research', 'explore', 2, 100, 'review', array['mapping','research']::text[]),
    ('dbbbf58e-d51e-5a68-b40e-64267511c8e1'::uuid, -- drawdown-enhance-high-speed-rail
     'Plan a trip by train instead of a short flight',
     'Pick a trip you or your family might take that people usually fly, and plan how you could make it by train instead, using official rail operator websites. Write up the route, the connections and the door-to-door travel time compared with flying. Post your plan; you don''t have to book anything.',
     'research', 'explore', 1, 100, 'review', array['research','planning']::text[]),
    ('f9ca7b5a-ce23-5eab-a159-c2a5f5474256'::uuid, -- drawdown-improve-ocean-shipping-efficiency
     'Follow one cargo ship''s voyage for a week',
     'Use a free public ship-tracking website to pick one container ship or cargo ship and check on it each day for a week. Note where it goes, how fast it travels and which ports it visits, then write a short post about what you learned about global shipping. Post screenshots and your notes.',
     'research', 'explore', 1, 100, 'review', array['research','observation']::text[]),
    ('672ab8e1-4259-500a-8c6d-60fab989f0af'::uuid, -- drawdown-improve-supply-chain-efficiency
     'Map where a week of your groceries comes from',
     'For a week, check the labels on the groceries your household buys to see where each item was grown or made. Mark the places on a map and note which items came from nearby and which traveled far. Post a photo or screenshot of your map.',
     'research', 'explore', 1, 100, 'review', array['mapping','observation']::text[]),
    ('ad54f184-7484-5ce2-827b-c431a13b6112'::uuid, -- drawdown-improve-truck-efficiency
     'Share your area''s rules on vehicle idling',
     'Look up whether your city, state or country has official rules on leaving engines running while parked, often called anti-idling rules. Make a short, friendly post or flyer with the official link, especially for places like school pickup lines or loading zones. Post a photo or link of what you shared.',
     'education', 'create', 1, 100, 'review', array['research','writing']::text[]),
    ('2ef53c00-7044-51b7-88c5-d5f3b4acd312'::uuid, -- drawdown-hold-virtual-meetings
     'Teach someone to join a video call',
     'Help a neighbor, relative or community group member who isn''t comfortable with video calls learn to join one, so they can take part in meetings without traveling. Use a free, well-known app on their own device and practice with a short test call. Post a short note or photo of your session, with their permission.',
     'mutual_aid', 'help', 1, 100, 'review', array['teaching','mutual_aid']::text[]),
    ('0cd5b19c-24c0-5104-833e-3342d928d644'::uuid, -- drawdown-improve-forest-management
     'Share your community''s wildfire plan in plain words',
     'Look up your area''s official wildfire or forest plan, such as a community wildfire protection plan, on your local fire department, forest agency or emergency management website. Summarize the main points in plain words and link to the official preparedness guidance; if your area has no wildfire plan, summarize the management plan for a nearby public forest instead. Post your summary.',
     'education', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('bada6edd-da39-5432-8371-787826da1ae9'::uuid, -- drawdown-deploy-precision-fermentation
     'Explain how microbes can brew food ingredients',
     'Precision fermentation uses microbes like yeast to make specific food ingredients, such as proteins found in milk or eggs. Read reliable sources and make a short explainer, comic or video comparing it with familiar fermentation like bread or yogurt. Post it with your sources.',
     'education', 'create', 2, 100, 'review', array['research','teaching']::text[]),
    ('3dff93b8-f019-504d-86fa-bf2149494a7b'::uuid, -- drawdown-manage-increase-urban-trees
     'Map the shade trees along a few local blocks',
     'Walk a few blocks you know well on the sidewalk, such as near a park, school or main street, and map the street trees and shady spots, noting bus stops, playgrounds and benches with no shade. Check whether your city has a program for requesting a street tree, and share it with neighbors. Post your map and the program link.',
     'advocacy', 'explore', 1, 100, 'review', array['mapping','observation']::text[]),
    ('bec0d368-558d-5579-85a3-94f0bf1a4aff'::uuid, -- drawdown-restore-abandoned-farmland
     'Compare old and new maps of farmland near you',
     'Use a free online archive of old maps or aerial photos and compare it with a current map of an area near you. Mark places that used to be farmed and are now turning back into woods, meadow or something else. Post side-by-side screenshots with your notes.',
     'research', 'explore', 2, 100, 'review', array['mapping','research']::text[]),
    ('a8058210-5be8-5931-b1d1-8eddbe6d233c'::uuid, -- drawdown-deploy-agroforestry
     'Visit a public food forest or orchard',
     'Find a food forest, community orchard or farm that welcomes visitors and grows trees together with crops, and spend some time there learning how the layers of plants work together. If there isn''t one near you, find one online and make a short explainer instead. Post a photo essay or your explainer.',
     'research', 'explore', 1, 100, 'review', array['observation','photography']::text[]),
    ('4c8ab486-7307-5931-b7e9-c52f39621ee8'::uuid, -- drawdown-deploy-biomass-crops-on-degraded-land
     'Map vacant and worn-out land in your area',
     'Use public maps, city records or land-use data to find vacant lots, old industrial land or worn-out farmland in your area. Make a simple map and note which sites, if any, have public plans for new uses. Post your map with sources.',
     'research', 'explore', 2, 100, 'review', array['mapping','research']::text[]),
    ('a4b81a7c-fb6d-514a-b374-44257864fa4a'::uuid, -- drawdown-deploy-perennial-crops
     'Map fruit and nut trees in public spaces',
     'Walk through parks, public paths and the planting strips along streets, and map the fruit and nut trees and other plants that produce food year after year, leaving trees in private yards off the map. Check whether a local group or the land manager allows public picking, and note it on your map. Post your map.',
     'research', 'explore', 1, 100, 'review', array['mapping','observation']::text[]),
    ('43870b45-575d-5eab-a8ab-62dff97cbd64'::uuid, -- drawdown-deploy-heat-pump-water-heaters
     'Find out what heats your home''s hot water',
     'Look for the label on your home''s water heater, if you can see it without moving anything, to find out whether it runs on gas, electricity or a heat pump. If you rent and can''t see it, ask your landlord or building manager. Post a short note on what you learned, with a photo of the label if you have one.',
     'education', 'explore', 1, 100, 'review', array['observation','research']::text[]),
    ('480815e2-a8a7-5ffa-9365-7c7c6144bb5a'::uuid, -- drawdown-deploy-solar-hot-water-heaters
     'Run a sunshine water-warming demo',
     'On a sunny day, fill two plastic bottles with water, wrap one in black paper or cloth, and leave both in the sun for a few hours. Feel the difference, or check with a kitchen thermometer, and explain how solar water heaters use the same idea to warm water for homes. Post a photo or short video of your demo and what you noticed; it works well with kids.',
     'education', 'create', 1, 100, 'review', array['teaching','video']::text[]),
    ('c0b0ff89-2db0-5cfd-b384-3498c60fcd39'::uuid, -- drawdown-increase-building-deconstruction-recycling
     'Map where to find reused building materials',
     'Find the stores, salvage yards and swap groups near you that sell or give away used building materials, such as doors, tiles, lumber and fixtures. Put them on a simple map or list with hours and a link for each, so neighbors fixing up a home on a tight budget know where to look. Post your map or list.',
     'community', 'explore', 1, 100, 'review', array['research','mapping']::text[]),
    ('39bd46c7-59ff-5ae0-9149-8286497cb6bf'::uuid, -- drawdown-deploy-ocean-power
     'Make a kids'' quiz about power from waves and tides',
     'Read about how waves and tides can be used to make electricity from reliable sources, then write a short, friendly quiz for kids with an answer sheet. Try it with a young relative, a class or a youth group if you can. Post a photo or copy of your quiz and answers.',
     'education', 'create', 1, 100, 'review', array['teaching','writing']::text[]),
    ('9feafb02-8fcc-56b9-a896-b99512fbcd8a'::uuid, -- drawdown-deploy-small-hydropower
     'Map the dams and small hydro plants near you',
     'Use public maps or databases from your water or energy agency to find dams and small hydropower plants on rivers near you. Mark them on a simple map and note which ones make electricity, if the source says so. Post your map with source links.',
     'research', 'explore', 2, 100, 'review', array['research','mapping']::text[]),
    ('0dad8ffa-ebfd-50b2-b614-0dceb7c34565'::uuid, -- drawdown-deploy-utility-scale-hydropower
     'Tell the story of a big dam in your region',
     'Choose a large dam in your region or country and read published sources about it, including the power it provides and how it affected people and rivers upstream and downstream. Write a short, balanced story or timeline that includes more than one point of view, and list your sources. Post it.',
     'research', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('d517b83f-d4ab-5908-890d-fbe2dbf883b3'::uuid, -- drawdown-deploy-bioelectricity-with-carbon-capture-storage
     'Write a fair Q&A on bioenergy with carbon capture',
     'Read reliable sources about making power from plants or plant waste while capturing the carbon dioxide and storing it underground. Write a short question-and-answer sheet that covers how it works, what supporters hope for and what critics worry about, with sources. Post it.',
     'research', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('2c835624-5420-5c50-b650-aa4c318a596b'::uuid, -- drawdown-deploy-advanced-biofuels
     'Make a plain-words guide to biofuels',
     'Read reliable sources about the different kinds of biofuels, from those made from food crops to newer ones made from waste oils and farm leftovers. Make a short guide or chart that explains the differences and the open questions in plain words. Post it with sources.',
     'education', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('66d427db-388f-5c92-97c5-6598d8490a0d'::uuid, -- drawdown-improve-routing-logistics
     'Team up with a neighbor to combine errands',
     'Plan your errands for the week as one efficient loop, and offer to pick up a few things for a neighbor who has trouble getting out, so one trip does the job of two. Agree clearly on what you''ll pick up and how it will be paid for, and keep the receipts. Post a short note on how it went, without names, addresses or your route.',
     'mutual_aid', 'help', 1, 100, 'review', array['mutual_aid','planning']::text[]),
    ('4357d930-c114-5e45-a22c-335b9eab43d4'::uuid, -- drawdown-produce-bio-oils
     'Explain storing carbon in oil made from plant waste',
     'Some companies heat plant waste without oxygen to make a thick bio-oil, then store it deep underground to keep its carbon out of the air. Read reliable sources and make a short, balanced explainer of how it works and what questions remain. Post it with sources.',
     'education', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('3c32fd6a-1abe-569f-a395-c4309d76d301'::uuid, -- drawdown-deploy-clean-cooking
     'Ask an elder how your family used to cook',
     'Ask a parent, grandparent or older neighbor how meals were cooked when they were young: what fuel they used, where the smoke went and how cooking has changed since. Write down or record their story with their permission. Post a short write-up or audio clip.',
     'research', 'explore', 1, 100, 'review', array['interviewing','writing']::text[])
  ) as v(id, title, description, domain, discovery_category, difficulty, base_points, verification_mode, skills)
on conflict (id) do nothing;

